  "a_sentences": [
    {
      "a_text": "Der Streitgegenstand war die Frage, ob die versicherte Person über den 31. März 2017 hinaus Anspruch auf eine Invalidenrente der Invalidenversicherung hat.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Das Bundesgericht kann auf seine Urteile nur zurückkommen, wenn einer der in den Art. 121 ff. BGG abschliessend aufgeführten Revisionsgründe vorliegt.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Die um Revision ersuchende Person muss einen vom Gesetz vorgesehenen Revisionsgrund nennen und aufzeigen, weshalb das revisionsbetroffene Urteil an einem revisionserheblichen Mangel leidet.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Es genügt nicht, das Vorliegen eines Revisionsgrunds einfach zu behaupten; vielmehr muss dargetan werden, weshalb dieser gegeben und inwiefern gestützt darauf das Urteilsdispositiv abzuändern ist.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Ausführungen der versicherten Person zur Unfallkausalität oder anderen Streitigkeiten der Unfallversicherung sowie Vorbringen zu ihrem Gesundheitszustand nach dem 15. Juli 2021, zu Operationen und zur Begutachtung im Jahr 2025 zielen an der Sache vorbei.",
      "b_propositions": ["P5", "P6"]
    },
    {
      "a_text": "Auf die unzähligen Willkürrügen ist nicht einzugehen.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Das Revisionsgesuch ist abzuweisen, soweit darauf überhaupt eingetreten werden kann.",
      "b_propositions": ["P8"]
    }
  ]
}
